const lockVariants = `-- name: LockVariants :many
SELECT
    pv.id,
    pv.stock,
    EXISTS (SELECT 1 FROM storefront_variants sv WHERE sv.id = pv.id) AS available
FROM product_variants pv
WHERE pv.id = ANY($1::uuid[])
ORDER BY pv.id
FOR UPDATE OF pv
`

type LockVariantsRow struct {
	ID        pgtype.UUID `json:"id"`
	Stock     int32       `json:"stock"`
	Available bool        `json:"available"`
}

// Locks the variants an order takes stock from, in id order so two
// checkouts sharing variants can't deadlock. available is whether each is
// still on sale.
func (q *Queries) LockVariants(ctx context.Context, ids []pgtype.UUID) ([]LockVariantsRow, error) {
	rows, err := q.db.Query(ctx, lockVariants, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LockVariantsRow{}
	for rows.Next() {
		var i LockVariantsRow
		if err := rows.Scan(&i.ID, &i.Stock, &i.Available); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

