const takeStock = `-- name: TakeStock :exec
UPDATE product_variants pv
SET stock = pv.stock - x.quantity
FROM (SELECT unnest($1::uuid[]) AS id, unnest($2::int[]) AS quantity) AS x
WHERE pv.id = x.id
`

type TakeStockParams struct {
	Ids        []pgtype.UUID `json:"ids"`
	Quantities []int32       `json:"quantities"`
}

// Reserves stock for an order; the caller checked it under LockVariants.
// two unnests in one select list pair up element by element
func (q *Queries) TakeStock(ctx context.Context, arg TakeStockParams) error {
	_, err := q.db.Exec(ctx, takeStock, arg.Ids, arg.Quantities)
	return err
}
